patch:
diff --git a/repro/no-var-tdz.js b/repro/no-var-tdz.js
new file mode 100644
index 0000000..f6a1189
--- /dev/null
+++ b/repro/no-var-tdz.js
@@ -0,0 +1,38 @@
+"use strict";
+// Repro: no-var autofix turns use-before-`var` into a TDZ ReferenceError.
+// Usage: node repro/no-var-tdz.js [path-to-eslint-package]   (default: this checkout)
+const path = require("node:path");
+const vm = require("node:vm");
+
+const pkg = process.argv[2] ? path.resolve(process.argv[2]) : path.join(__dirname, "..");
+const { Linter } = require(path.join(pkg, "lib/api"));
+const version = require(path.join(pkg, "package.json")).version;
+
+const code = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}`;
+
+const linter = new Linter({ configType: "flat" });
+const config = [{ rules: { "no-var": ["error"] } }];
+const messages = linter.verify(code, config, "x.js");
+const { output, fixed } = linter.verifyAndFix(code, config, { filename: "x.js" });
+
+function run(src) {
+    const body = src.replace("export function", "function") + "\na();";
+    try {
+        vm.runInNewContext(body, { console: { log() {} } });
+        return "ok";
+    } catch (e) {
+        return `${e.name}: ${e.message}`;
+    }
+}
+
+console.log(`eslint ${version}`);
+console.log("messages:", messages.map(m => `${m.line}:${m.column} ${m.message} (${m.ruleId}) fixable=${!!m.fix}`));
+console.log("fixed:", fixed);
+console.log("--- output ---\n" + output + "\n--------------");
+console.log("run original:", run(code));
+console.log("run output:  ", run(output));
+process.exitCode = run(output) === "ok" ? 0 : 1;
